(function(){AppModule.register({routes:[
{path:"production/board",title:"导演与分镜",permission:"production.write",render(){return UI.head("导演与分镜","将已审核剧本拆解为集、场、镜头生产单元。",UI.btn("＋ 添加镜头单元","new-shot","primary"))+UI.card("镜头生产单元",UI.table(["镜头","集 / 场","画面与动作","引用资产","时长","状态"],'<tr><td>SH-017-04</td><td>第 17 集 / 03 场</td><td>雨夜街口，人物回头停步</td><td>顾沉 v3 · 雨夜场景 v2</td><td>6 秒</td><td>'+UI.tag("待生产")+'</td></tr><tr><td>SH-017-05</td><td>第 17 集 / 03 场</td><td>近景对白，情绪克制</td><td>顾沉 v3</td><td>8 秒</td><td>'+UI.tag("待生产")+'</td></tr><tr><td>SH-017-06</td><td>第 17 集 / 04 场</td><td>远景，车辆驶离</td><td>旧城区 v2</td><td>5 秒</td><td>'+UI.tag("已确认")+'</td></tr>'))+'<div class="notice" style="margin-top:14px">镜头需关联剧本版本、场景、人物、对白、参考资产、前后镜头关系和质量标准。修改正式剧本后先执行影响分析。</div>';}},
{path:"production/generation",title:"视频与音频生产",permission:"production.write",render(){const rows=DB.tasks.map(t=>'<tr><td>'+t.id+'</td><td>'+t.name+'</td><td>'+t.type+'</td><td>'+t.model+'</td><td>'+UI.tag(t.status)+'</td><td>¥'+t.cost+'</td><td><button class="btn" data-action="task-retry">重试 / 处理</button></td></tr>').join("");return UI.head("视频与音频生产","任务真实状态应来自供应商回执、文件回收和质量校验。")+UI.card("生产任务台账",'<div class="toolbar"><span class="pill blue">演示任务 '+DB.tasks.length+' 项</span>'+UI.btn("暂停派发","task-pause")+'</div>'+UI.table(["任务 ID","任务名称","能力","模型","状态","实际费用（演示）","操作"],rows))+'<div class="notice warn" style="margin-top:14px">供应商返回成功 ≠ 文件下载成功 ≠ 资产保存成功 ≠ 质量通过。四个状态必须独立记录；失败和重试费用不得丢失。</div>';}},
{path:"production/delivery",title:"后期与交付",permission:"delivery.write",render(){return UI.head("后期与交付","组织镜头、对白、音乐、音效和字幕，完成成片质检与正式交付。")+ '<div class="grid grid-2">'+UI.card("后期时间线 · 第 17 集",'<div class="list">'+["视频轨 V1 · 12 个镜头","对白轨 D1 · 18 条对白","音乐轨 M1 · 2 段配乐","音效轨 S1 · 9 个音效","字幕轨 C1 · 18 条字幕"].map(x=>'<div class="list-row"><span>'+x+'</span>'+UI.tag("已编排")+'</div>').join("")+'</div><div class="head-actions" style="margin-top:14px">'+UI.btn("生成预览","generate","primary")+' '+UI.btn("执行质量检测","noop")+'</div>')+UI.card("最终成片审核",'<div class="notice">最终审核前应完成所有集数合成、文件校验和质量检查。</div><div class="list" style="margin-top:12px">'+["剧情完整性","人物与场景连续性","画面质量","配音与音画同步","字幕准确性","集数和交付文件完整"].map(x=>'<div class="list-row"><span>'+x+'</span><input type="checkbox"></div>').join("")+'</div><div class="head-actions" style="margin-top:14px">'+UI.btn("指定问题返工","return-script")+' '+UI.btn("通过并交付","final-approve","primary")+'</div>')+'</div>';}}
]});})();